{
  "decision-prism-changes-within-a-traverse": "SELECT s.shot_id, s.raw_mm + n.delta_mm AS corrected_mm, n.source_id FROM range_shots AS s LEFT JOIN prism_notes AS n ON n.run_id = s.run_id AND n.tick = (SELECT MAX(p.tick) FROM prism_notes AS p WHERE p.run_id = s.run_id AND p.tick <= s.tick) WHERE s.run_id = 'R' ORDER BY s.tick, s.shot_id;",
  "decision-project-unsampled-breakage": "WITH samples AS (SELECT grade, SUM(inspected_units) AS sampled_units, SUM(broken_units) AS broken_sample_units FROM carton_audits WHERE broken_units IS NOT NULL GROUP BY grade) SELECT s.grade, s.sampled_units, s.broken_sample_units, (s.broken_sample_units * u.unopened_units * u.unit_cost_cents + s.sampled_units / 2) / s.sampled_units AS reserve_cents FROM samples AS s JOIN unopened_stock AS u ON u.grade = s.grade ORDER BY s.grade;",
  "decision-publish-certified-relay-patch": "WITH ranked AS (SELECT club_name, card_pts, card_ref, ROW_NUMBER() OVER (PARTITION BY club_name ORDER BY revision_no DESC) AS rn FROM relay_cards), records AS (SELECT '\"' || replace(b.club_name, '\"', '\"\"') || '\",' || printf('%d', r.card_pts) || ',' || r.card_ref || char(10) AS line FROM relay_board AS b JOIN ranked AS r ON r.club_name = b.club_name WHERE r.rn = 1 AND r.card_pts <> b.board_pts ORDER BY b.club_name COLLATE BINARY) SELECT 'club,points,source' || char(10) || coalesce(group_concat(line, ''), '') AS csv_body FROM records;",
  "decision-quarterly-tier-close-with-usage-corrections": "WITH closes AS (SELECT account_code, SUM(CASE WHEN posting_day < '2026-04-01' THEN signed_units ELSE 0 END) AS opening_units, SUM(signed_units) AS closing_units FROM meter_posting WHERE posting_state = 'posted' AND posting_day BETWEEN '2026-03-01' AND '2026-04-30' GROUP BY account_code HAVING COUNT(CASE WHEN posting_day >= '2026-04-01' THEN 1 END) > 0) SELECT account_code, opening_units, closing_units, 3 * (closing_units - opening_units) + 5 * (MIN(closing_units, 100) - MIN(opening_units, 100)) AS april_revenue_cents FROM closes ORDER BY account_code;"
}
